{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Earnings Prep Data",
    "url": "http://localhost:7805",
    "widgets_json": {
      "click_revision_table": {
        "name": "Click Revision Table",
        "description": "Revision rows whose symbol cell syncs the app.",
        "endpoint": "/click-revision-table",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "symbol",
                "headerName": "Symbol",
                "cellDataType": "text",
                "renderFn": "cellOnClick",
                "renderFnParams": {
                  "actionType": "groupBy",
                  "groupByParamName": "symbol"
                }
              },
              {
                "field": "revision_pct",
                "headerName": "Revision %",
                "cellDataType": "number",
                "formatterFn": "percent"
              }
            ]
          }
        }
      },
      "earnings_chart": {
        "name": "EPS History",
        "description": "Plotly EPS beat/miss history.",
        "endpoint": "/eps-history",
        "type": "chart",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "raw": true,
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ]
      }
    },
    "apps_json": [
      {
        "name": "Click Revision Desk",
        "description": "Clickable revisions and EPS history.",
        "tabs": {
          "table": {
            "id": "table",
            "name": "Table",
            "layout": [
              {
                "i": "click_revision_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "chart": {
            "id": "chart",
            "name": "Chart",
            "layout": [
              {
                "i": "earnings_chart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Click Revision Sync",
            "type": "param",
            "paramName": "symbol",
            "widgetIds": [
              "click_revision_table",
              "earnings_chart"
            ]
          }
        ]
      }
    ]
  }
}
